import { test, expect } from '@playwright/test';

test.describe('Update Display Name Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
  });

  test('should successfully update display name and reflect it across the app', async ({ page }) => {
    // Verify initial display name
    const displayName = page.getByRole('heading', { name: /John Doe/i });
    await expect(displayName).toBeVisible();

    // Locate and fill in the display name input field
    const displayNameInput = page.getByLabel('Display Name');
    await expect(displayNameInput).toBeVisible();
    await displayNameInput.fill('Jane Smith');

    // Locate and click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/display name updated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify updated display name is reflected
    await expect(displayName).toHaveText('Jane Smith');

    // Verify updated display name is reflected in profile header
    const profileHeader = page.getByRole('heading', { name: /Jane Smith/i });
    await expect(profileHeader).toBeVisible();
  });

  test('should handle empty display name input and prevent update', async ({ page }) => {
    // Verify initial display name
    const displayName = page.getByRole('heading', { name: /John Doe/i });
    await expect(displayName).toBeVisible();

    // Locate and fill in the display name input field with empty string
    const displayNameInput = page.getByLabel('Display Name');
    await expect(displayNameInput).toBeVisible();
    await displayNameInput.fill('');

    // Locate and click the save button
    const saveButton = page.getByRole('button', { name: /save/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify error message appears
    const errorMessage = page.getByText(/display name cannot be empty/i);
    await expect(errorMessage).toBeVisible();

    // Verify display name was not updated
    await expect(displayName).toHaveText('John Doe');

    // Verify success message does not appear
    const successMessage = page.getByText(/display name updated successfully/i);
    await expect(successMessage).not.toBeVisible();
  });
});
